import{_ as e,o,c as d,ap as a}from"./chunks/framework.BWFd5M2R.js";const g=JSON.parse('{"title":"HTML 实体与字符编码","description":"","frontmatter":{"password":"f364e34a3743eacf1767066da4b2699469e2f9fab3b63fdd112c672a3805497e"},"headers":[],"relativePath":"HTML/HTML实体与字符编码.md","filePath":"HTML/HTML实体与字符编码.md","lastUpdated":1773652575000}'),r={name:"HTML/HTML实体与字符编码.md"};function c(n,t,l,s,i,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="html-实体与字符编码" tabindex="-1">HTML 实体与字符编码 <a class="header-anchor" href="#html-实体与字符编码" aria-label="Permalink to “HTML 实体与字符编码”">​</a></h1><h2 id="字符编码" tabindex="-1">字符编码 <a class="header-anchor" href="#字符编码" aria-label="Permalink to “字符编码”">​</a></h2><ul><li>文档用 <strong><code>UTF-8</code></strong> 时，在 <code>&lt;head&gt;</code> 靠前写 <code>&lt;meta charset=&quot;UTF-8&quot; /&gt;</code>，避免中文乱码。</li><li><strong>字节序</strong>：UTF-8 无 endian 问题；UTF-16 文件可能带 BOM。</li><li><strong>HTTP <code>Content-Type</code></strong> 里的 <code>charset</code> 与文档声明应一致；冲突时以能覆盖的一方为准（具体依浏览器）。</li></ul><h2 id="html-字符实体" tabindex="-1">HTML 字符实体 <a class="header-anchor" href="#html-字符实体" aria-label="Permalink to “HTML 字符实体”">​</a></h2><p>在 HTML 里显示 <strong><code>&lt;</code>、<code>&gt;</code>、<code>&amp;</code>、引号、空格</strong> 等，可用实体，避免被当成标签或断行规则吃掉。</p><table tabindex="0"><thead><tr><th>显示</th><th>常见写法</th></tr></thead><tbody><tr><td><code>&lt;</code></td><td><code>&amp;lt;</code></td></tr><tr><td><code>&gt;</code></td><td><code>&amp;gt;</code></td></tr><tr><td><code>&amp;</code></td><td><code>&amp;amp;</code></td></tr><tr><td>双引号</td><td><code>&amp;quot;</code></td></tr><tr><td>不换行空格</td><td><code>&amp;nbsp;</code></td></tr></tbody></table><p>也可用 <strong>数字实体</strong>：<code>&amp;#169;</code>（©）、<code>&amp;#x00A9;</code>（十六进制）。<br><strong>UTF-8 页面</strong>可直接输入 Unicode 字符，实体多用于<strong>与语法冲突</strong>或<strong>老环境兼容</strong>。</p><h2 id="和-url-js-的区别" tabindex="-1">和 URL / JS 的区别 <a class="header-anchor" href="#和-url-js-的区别" aria-label="Permalink to “和 URL / JS 的区别”">​</a></h2><ul><li><strong>URL</strong> 里非 ASCII 常 <strong>percent-encoding</strong>（<code>encodeURIComponent</code>）。</li><li><strong>JS 字符串</strong>是 UTF-16 单元序列；DOM 文本与 HTML 实体由解析器转换。</li></ul><blockquote><p>MDN：<a href="https://developer.mozilla.org/zh-CN/docs/Glossary/Entity" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Glossary/Entity</a></p></blockquote>',10)])])}const m=e(r,[["render",c]]);export{g as __pageData,m as default};
